// ============================================================================
// ARM_Local_Translation_Interface_apb: APB4 register wrapper around ARM_Local_Translation_Interface_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/ARM_Local_Translation_Interface.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/ARM_Local_Translation_Interface.md
// ============================================================================
module ARM_Local_Translation_Interface_apb #(
  parameter int NE = 8,
  parameter int RQ = 4,
  parameter int NCT = 8
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic lm_open_req,
  output logic lm_open_ack,
  input logic la_valid,
  input logic [3:0] la_id,
  input logic [19:0] la_va,
  input logic [7:0] la_sid,
  input logic [7:0] la_ssid,
  input logic la_ssidv,
  input logic [1:0] la_rw,
  input logic la_instr,
  input logic la_priv,
  output logic la_credit,
  output logic lr_valid,
  output logic [3:0] lr_id,
  output logic [1:0] lr_resp,
  output logic [19:0] lr_pa,
  output logic [7:0] lr_attr,
  output logic [$clog2(NCT)-1:0] lr_ctag,
  input logic lc_valid,
  input logic [$clog2(NCT)-1:0] lc_ctag
);
  localparam logic [31:0] ID_VALUE = 32'h4C540200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cfg_we;
  logic [2:0]    c_cfg_idx;
  logic          c_cfg_v;
  logic [7:0]    c_cfg_sid;
  logic [7:0]    c_cfg_ssid;
  logic          c_cfg_ssidv;
  logic [19:0]   c_cfg_va;
  logic [19:0]   c_cfg_pa;
  logic [3:0]    c_cfg_perm;
  logic [7:0]    c_cfg_attr;
  logic          c_inv_valid;
  logic          c_inv_ready;
  logic          c_inv_all;
  logic [7:0]    c_inv_sid;
  logic          c_inv_done;
  logic [3:0]    c_ctags_out;
  logic          c_ev_fault;
  logic          c_ev_proto;
  ARM_Local_Translation_Interface_top #(.NE(NE), .RQ(RQ), .NCT(NCT)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .lm_open_req(lm_open_req),
    .lm_open_ack(lm_open_ack),
    .la_valid(la_valid),
    .la_id(la_id),
    .la_va(la_va),
    .la_sid(la_sid),
    .la_ssid(la_ssid),
    .la_ssidv(la_ssidv),
    .la_rw(la_rw),
    .la_instr(la_instr),
    .la_priv(la_priv),
    .la_credit(la_credit),
    .lr_valid(lr_valid),
    .lr_id(lr_id),
    .lr_resp(lr_resp),
    .lr_pa(lr_pa),
    .lr_attr(lr_attr),
    .lr_ctag(lr_ctag),
    .lc_valid(lc_valid),
    .lc_ctag(lc_ctag),
    .cfg_we(c_cfg_we),
    .cfg_idx(c_cfg_idx),
    .cfg_v(c_cfg_v),
    .cfg_sid(c_cfg_sid),
    .cfg_ssid(c_cfg_ssid),
    .cfg_ssidv(c_cfg_ssidv),
    .cfg_va(c_cfg_va),
    .cfg_pa(c_cfg_pa),
    .cfg_perm(c_cfg_perm),
    .cfg_attr(c_cfg_attr),
    .inv_valid(c_inv_valid),
    .inv_ready(c_inv_ready),
    .inv_all(c_inv_all),
    .inv_sid(c_inv_sid),
    .inv_done(c_inv_done),
    .ctags_out(c_ctags_out),
    .ev_fault(c_ev_fault),
    .ev_proto(c_ev_proto)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [24:0] h_TBL0;   // 12'h014 TBL0 holding register
  logic [27:0] h_TBL1;   // 12'h018 TBL1 holding register
  logic [19:0] h_TBL2;   // 12'h01C TBL2 holding register
  logic [8:0] h_INV;   // 12'h020 INV holding register
  logic vld_TBL;
  logic full_INV;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      h_TBL0 <= '0;
      h_TBL1 <= '0;
      h_TBL2 <= '0;
      h_INV <= '0;
      vld_TBL <= 1'b0;
      full_INV <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) h_TBL0 <= (h_TBL0 & ~wmask[24:0]) | (PWDATA[24:0] & wmask[24:0]);
      if (wr && hit[6]) h_TBL1 <= (h_TBL1 & ~wmask[27:0]) | (PWDATA[27:0] & wmask[27:0]);
      if (wr && hit[7]) h_TBL2 <= (h_TBL2 & ~wmask[19:0]) | (PWDATA[19:0] & wmask[19:0]);
      vld_TBL <= wr && hit[7];
      if (wr && hit[8] && !full_INV) h_INV <= (h_INV & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[8] && !full_INV) full_INV <= 1'b1;
      else if (full_INV && c_inv_ready) full_INV <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_sid[7:0] = h_TBL0[7:0];
  assign c_cfg_ssid[7:0] = h_TBL0[15:8];
  assign c_cfg_ssidv = h_TBL0[16:16];
  assign c_cfg_idx[2:0] = h_TBL0[19:17];
  assign c_cfg_v = h_TBL0[20:20];
  assign c_cfg_perm[3:0] = h_TBL0[24:21];
  assign c_cfg_va[19:0] = h_TBL1[19:0];
  assign c_cfg_attr[7:0] = h_TBL1[27:20];
  assign c_cfg_pa[19:0] = h_TBL2[19:0];
  assign c_inv_all = h_INV[0:0];
  assign c_inv_sid[7:0] = h_INV[8:1];
  assign c_cfg_we = vld_TBL;
  assign c_inv_valid = full_INV;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_fault;
    irq_set[1] = c_ev_proto;
    irq_set[2] = c_inv_done;
    irq_set[3] = full_INV & c_inv_ready;
    irq_set[4] = wr & (hit[8]) & full_INV;
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {full_INV};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(h_TBL0);
      10'd6: apb_rdata = 32'(h_TBL1);
      10'd7: apb_rdata = 32'(h_TBL2);
      10'd8: apb_rdata = 32'(h_INV);
      10'd9: apb_rdata = 32'({c_ctags_out});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
